mapper.select:
SELECT id, tenant_code, session_id, msg_no, client_msg_no, seq, msg_type, sender_type, sender_id,
       content, send_time
  FROM session_message
 WHERE tenant_code = #{tenantCode}
   AND session_id = #{sessionId}
   AND is_deleted = FALSE
 ORDER BY seq, id
 LIMIT #{limit}

SELECT id, tenant_code, session_id, msg_no, client_msg_no, seq, msg_type, sender_type, sender_id,
       content, status, visible_to, send_time
  FROM session_message
 WHERE tenant_code = #{tenantCode}
   AND session_id = #{sessionId}
   AND is_deleted = FALSE

   AND id < #{beforeId}


   AND visible_to = #{visibleTo}

 ORDER BY seq DESC, id DESC
 LIMIT #{limit}

SELECT id, tenant_code, session_id, msg_no, client_msg_no, seq, msg_type, sender_type, sender_id,
       content, status, visible_to, send_time
  FROM session_message
 WHERE tenant_code = #{tenantCode}
   AND session_id = #{sessionId}
   AND client_msg_no = #{clientMsgNo}
   AND is_deleted = FALSE
 LIMIT 1

SELECT id, tenant_code, session_id, msg_no, client_msg_no, seq, msg_type, sender_type, sender_id,
       content, status, visible_to, send_time
  FROM session_message
 WHERE tenant_code = #{tenantCode}
   AND session_id = #{sessionId}
   AND is_deleted = FALSE
   AND seq > #{afterSeq}

   AND visible_to = #{visibleTo}

 ORDER BY seq, id
 LIMIT #{limit}
